// Prints the extension of a file name: the part after the LAST '.'.
void print_ext(const char *name) {
    const char *dot = strrchr(name, '.');
    if (dot == NULL) {
        printf("%s: no extension\n", name);
    }
    else {
        printf("%s: %s\n", name, dot + 1);
    }
}

