#include <stdio.h>
#include <string.h>

void print_iarr(const int *a, size_t n) {
    printf("%d", a[0]);
    for (size_t i = 1; i < n; i++) {
        printf(", %d", a[i]);
    }
}


int main(void) {

    int x[] = {1, 2, 3, 4, 5, 6};

    printf("before : ");
    print_iarr(x, 6);
    printf("\n");

    size_t index = 4;
    int *dest = x + index;
    int *src = dest + 1;
    size_t count = 6 - index - 1;
    memmove(dest, src, count * sizeof(int));

    printf("after  : ");
    print_iarr(x, 6);
    printf("\n");

    return 0;
}

#include <stdio.h>
#include <string.h>

// Removes the char at index i from the string s (i must be < strlen(s)).
void remove_at(char *s, size_t i) {
    size_t len = strlen(s);
    // move s[i + 1] ... s[len] (that is the '\0') one place to the left
    memmove(s + i, s + i + 1, len - i);
}

int main(void) {
    char word[] = "strings";
    remove_at(word, 0);
    printf("%s\n", word);
    remove_at(word, 5);
    printf("%s\n", word);
    remove_at(word, 2);
    printf("%s (length %zu)\n", word, strlen(word));
    return 0;
}

