// Tries to read year-month-day from s with the format fmt.
void show(const char *s, const char *fmt) {
    unsigned int y = 0;
    unsigned int m = 0;
    unsigned int d = 0;
    int n = sscanf(s, fmt, &y, &m, &d);
    printf("\"%s\" with \"%s\": n = %d, %u %u %u\n", s, fmt, n, y, m, d);
}

