#include <stdio.h>
#include <string.h>

// Returns how many times sub occurs in str, counting occurrences that
// do not overlap. sub must not be the empty string.
size_t count_sub(const char *str, const char *sub) {
    size_t count = 0;
    size_t len = strlen(sub);
    const char *p = strstr(str, sub);
    while (p != NULL) {
        count++;
        p = strstr(p + len, sub);   // search again after this occurrence
    }
    return count;
}

int main(void) {
    printf("%zu\n", count_sub("the cat sat on the mat", "at"));
    printf("%zu\n", count_sub("aaaa", "aa"));
    printf("%zu\n", count_sub("banana", "nab"));
    printf("%zu\n", count_sub("", "x"));
    return 0;
}

