#include <stdio.h>

// Reads a time written as H:MM or HH:MM from s into *h and *m.
// Returns 1 if both numbers were read and the time is valid
// (0 <= hours <= 23, 0 <= minutes <= 59); otherwise returns 0.
int parse_time(const char *s, int *h, int *m) {
    int n = sscanf(s, "%2d:%2d", h, m);
    if (n != 2) {
        return 0;
    }
    return *h >= 0 && *h <= 23 && *m >= 0 && *m <= 59;
}

int main(void) {
    const char *times[] = {"9:05", "23:59", "24:00", "noon", "7-30"};
    for (int i = 0; i < 5; i++) {
        int h;
        int m;
        if (parse_time(times[i], &h, &m)) {
            char out[30];
            sprintf(out, "%02d:%02d is minute %d", h, m, h * 60 + m);
            puts(out);
        }
        else {
            printf("bad time: %s\n", times[i]);
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

// names is an array of strings whose last element is NULL. Each name is one
// or more words separated by single spaces. For each name, writes into dest
// its first letter and, if it has more than one word, the first letter of its
// last word. The initials of different names are separated by one space.
// dest must be big enough (3 chars per name is always enough, plus 1).
void initials(char *names[], char *dest) {
    size_t k = 0;
    for (int i = 0; names[i] != NULL; i++) {
        if (i > 0) {
            dest[k] = ' ';
            k++;
        }
        dest[k] = names[i][0];
        k++;
        char *space = strrchr(names[i], ' ');
        if (space != NULL) {
            dest[k] = space[1];
            k++;
        }
    }
    dest[k] = '\0';
}

int main(void) {
    char *people[] = {"Ada Lovelace", "Grace Brewster Hopper", "Cher", NULL};
    char result[3 * 3 + 1];
    initials(people, result);
    printf("%s\n", result);

    char *nobody[] = {NULL};
    initials(nobody, result);
    printf("[%s]\n", result);
    return 0;
}
